Translate the following GNU C++14 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const long long MOD1 = 998244353;
const long long MOD2 = 1000000007;

long long read_input() {
    long long result = 0;
    int sign = 1;
    char ch = getchar();
    while (ch < '0' || ch > '9') {
        if (ch == '-') sign = -1;
        ch = getchar();
    }
    while (ch >= '0' && ch <= '9') {
        result = (result << 1) + (result << 3) + (ch - '0');
        ch = getchar();
    }
    return result * sign;
}

long long n;
vector<int> v[10];
long long sum[10];
long long cnt1 = 0, cnt2 = 0, ans = 0;
int pw[7] = {1, 10, 100, 1000, 10000, 100000, 1000000};

void dfs1(int len, long long val) {
    if (len > 6) return;
    v[len].push_back((cnt1 - val + MOD1) % MOD1);
    sum[len] += (cnt1 - val + MOD1) % MOD1;
    ++cnt1;
    for (int i = 0; i <= 9; ++i) {
        dfs1(len + 1, val * 10 + i);
    }
}

bool check(long long x) {
    return x * 1000000 + 999999 <= n && x * 10000000 > n;
}

void dfs2(int len, long long val) {
    if (val > n) return;
    if (check(val)) {
        for (int i = 0; i <= 6; ++i) {
            long long v1 = ((cnt2 + 1 - val * pw[i]) % MOD1 + MOD1) % MOD1;
            int num = lower_bound(v[i].begin(), v[i].end(), (int)(MOD1 - v1)) - v[i].begin();
            ans = (ans + (sum[i] + v[i].size() * v1 - 1LL * MOD1 * (v[i].size() - num))) % MOD2;
        }
        cnt2 += cnt1;
    } else {
        if (len) ++cnt2;
        ans = (ans + ((cnt2 - val) % MOD1 + MOD1) % MOD1) % MOD2;
        for (int i = (!len); i <= 9; ++i) {
            dfs2(len + 1, val * 10 + i);
        }
    }
}

int main() {
    n = read_input();
    dfs1(0, 0);
    for (int i = 0; i <= 6; ++i) {
        sort(v[i].begin(), v[i].end());
    }
    dfs2(0, 0);
    cout << ans << "\n";
    return 0;
}
</original_code>
